"""Synthesised SFX bed for the R7 REELSKILL reel (adapted from the R3 bed; no samples, no downloads — every sound is generated by this
code, which is what the VO claims: "sampai efek suaranya, semuanya kode"): mini-reel wall, credit panel (coins, strike, zero stamp),
prompt typing + send, code lines + file tabs, the video-AI vs code cards (error buzz, scissors snips), the four showcase mini-reels
(compile flashes, moon/stars twinkles, cartoon boings, koi bloops + splash, clapperboard + rain), the HyperFrames terminal + render,
the meta timeline, the CTA. Deterministic. Run: python3 tools/sfx.py ."""
import json, sys, wave
from pathlib import Path
import numpy as np

P = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
T = json.loads((P / "production/timing.json").read_text())
SR = 48000; N = int(T["total_sec"] * SR) + SR
out = np.zeros(N)
rng = np.random.default_rng(7)
S = {s["id"]: s for s in T["scenes"]}
def wt(txt, after=0.0):
    for w in T["words"]:
        if w["w"] == txt and w["s"] >= after: return w["s"]
    return None

def put(t, x, g=1.0):
    i = int(t * SR); j = min(N, i + len(x))
    if i < 0 or i >= N: return
    out[i:j] += g * x[: j - i]

def svf_bp(x, f, q=1.2):
    """state-variable band-pass with a per-sample centre frequency"""
    y = np.zeros_like(x); lo = bp = 0.0
    fs = 2 * np.sin(np.pi * np.clip(f, 20, SR / 6) / SR); d = 1.0 / q
    for n in range(len(x)):
        hp = x[n] - lo - d * bp; bp += fs[n] * hp; lo += fs[n] * bp; y[n] = bp
    return y

def env(n, a=0.35, shape=2.0):
    u = np.linspace(0, 1, n); k = int(n * a)
    e = np.ones(n); e[:k] = np.sin(np.linspace(0, np.pi / 2, k)) ** shape; e[k:] = np.cos(np.linspace(0, np.pi / 2, n - k)) ** shape
    return e

def whoosh(dur=0.6, f0=300, f1=2600, q=1.1, a=0.45):
    n = int(dur * SR); u = np.linspace(0, 1, n)
    f = f0 * (f1 / f0) ** (np.sin(np.pi * u * 0.5) ** 1.3)
    x = svf_bp(rng.standard_normal(n), f, q) * env(n, a)
    return x / (np.abs(x).max() + 1e-9)

def boom(dur=1.4, f0=95, f1=38):
    n = int(dur * SR); t = np.arange(n) / SR
    ph = 2 * np.pi * np.cumsum(f0 * (f1 / f0) ** (t / dur)) / SR
    x = np.sin(ph) * np.exp(-t * 3.2)
    nb = svf_bp(rng.standard_normal(n), np.full(n, 180.0), 0.8) * np.exp(-t * 9) * 0.6
    x = np.tanh(1.8 * (x + nb))
    return x / np.abs(x).max()

def pop(f0=900, f1=320, dur=0.09):
    n = int(dur * SR); t = np.arange(n) / SR
    x = np.sin(2 * np.pi * np.cumsum(f0 * (f1 / f0) ** (t / dur)) / SR) * np.exp(-t * 38)
    return x / np.abs(x).max()

def tick(dur=0.025, f=4200):
    n = int(dur * SR); t = np.arange(n) / SR
    x = svf_bp(rng.standard_normal(n), np.full(n, f), 2.0) * np.exp(-t * 260)
    return x / (np.abs(x).max() + 1e-9)

def square_blips(notes, step=0.055):
    out_ = []
    for f in notes:
        n = int(step * SR); t = np.arange(n) / SR
        out_.append(np.sign(np.sin(2 * np.pi * f * t)) * 0.6 * np.exp(-t * 18))
    return np.concatenate(out_)

def zap(dur=0.5):
    n = int(dur * SR); t = np.arange(n) / SR
    x = np.sin(2 * np.pi * np.cumsum(120 * (2400 / 120) ** (t / dur)) / SR) * env(n, 0.15) * 0.6
    x += np.sin(2 * np.pi * 60 * t) * 0.35 * np.exp(-t * 4) + 0.15 * np.sin(2 * np.pi * 15734 / 4 * t) * np.exp(-t * 10)
    return x / np.abs(x).max()

def chime(freqs=(1318.5, 1760, 2637), dur=1.4):
    n = int(dur * SR); t = np.arange(n) / SR; x = np.zeros(n)
    for k, f in enumerate(freqs):
        d = int(k * 0.06 * SR); tt = t[: n - d]
        x[d:] += np.sin(2 * np.pi * f * tt) * np.exp(-tt * 3.5) * (0.8 ** k)
    return x / np.abs(x).max()

def rip(dur=0.55):
    n = int(dur * SR); t = np.arange(n) / SR
    jit = np.repeat(rng.random(n // 240 + 1), 240)[:n] ** 3
    x = svf_bp(rng.standard_normal(n), np.linspace(1400, 3600, n), 1.4) * jit * env(n, 0.2)
    return x / np.abs(x).max()

def scribble(dur=0.6):
    n = int(dur * SR); t = np.arange(n) / SR
    am = 0.5 + 0.5 * np.sign(np.sin(2 * np.pi * 13 * t))
    x = svf_bp(rng.standard_normal(n), 2600 + 900 * np.sin(2 * np.pi * 6.5 * t), 1.6) * am * env(n, 0.2)
    return x / np.abs(x).max()

def rumble(dur=1.5):
    n = int(dur * SR); t = np.arange(n) / SR
    x = svf_bp(rng.standard_normal(n), np.linspace(70, 260, n), 0.7)
    x = x / np.abs(x).max() * env(n, 0.3, 1.0)
    return x


def flap():
    """split-flap clack: two quick clicks + a soft low knock"""
    x = np.zeros(int(0.22 * SR)); a = tick(0.02, 3000); b = tick(0.02, 2400)
    x[: len(a)] += a; i = int(0.11 * SR); x[i:i + len(b)] += 0.8 * b
    k = pop(180, 90, 0.08); x[: len(k)] += 0.35 * k
    return x / np.abs(x).max()

def rise(dur=0.6, f0=300, f1=1200):
    n = int(dur * SR); t = np.arange(n) / SR
    x = np.sin(2 * np.pi * np.cumsum(f0 * (f1 / f0) ** (t / dur)) / SR) * env(n, 0.8, 1.0) * (0.6 + 0.4 * np.sign(np.sin(2 * np.pi * 14 * t)))
    return x / np.abs(x).max()

def buzz(dur=0.35):
    n = int(dur * SR); t = np.arange(n) / SR
    x = (np.sign(np.sin(2 * np.pi * 110 * t)) * 0.5 + np.sign(np.sin(2 * np.pi * 116 * t)) * 0.5) * env(n, 0.05, 1.0)
    return x / np.abs(x).max()

def typing(t0, t1, gain=0.11, rate=16):
    k = 0; t = t0
    while t < t1:
        put(t, tick(0.02, 3600 + 500 * (k % 3)), gain * (0.8 + 0.2 * (k % 2))); k += 1; t += 1.0 / rate * (0.8 + 0.4 * ((k * 7) % 5) / 5)

def boing(dur=0.42, f0=180, f1=520):
    n = int(dur * SR); t = np.arange(n) / SR; u = t / dur
    f = f0 + (f1 - f0) * np.sin(np.pi * np.clip(u * 1.2, 0, 1)) + 18 * np.sin(2 * np.pi * 22 * t)
    x = np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t * 5) * np.minimum(1, t / 0.01)
    return x / np.abs(x).max()

def bloop(f0=260, f1=900, dur=0.14):
    n = int(dur * SR); t = np.arange(n) / SR
    x = np.sin(2 * np.pi * np.cumsum(f0 * (f1 / f0) ** (t / dur)) / SR) * np.exp(-t * 22) * np.minimum(1, t / 0.004)
    return x / np.abs(x).max()

def splash(dur=0.7):
    n = int(dur * SR); t = np.arange(n) / SR
    x = svf_bp(rng.standard_normal(n), np.linspace(3200, 900, n), 1.0) * np.exp(-t * 6) * np.minimum(1, t / 0.01)
    return x / np.abs(x).max()

def clack():
    x = np.zeros(int(0.2 * SR)); a = tick(0.012, 2600); k = pop(220, 80, 0.1)
    x[: len(a)] += a; x[: len(k)] += 0.7 * k
    return x / np.abs(x).max()

def coin():
    n = int(0.5 * SR); t = np.arange(n) / SR; x = np.zeros(n)
    for d, f in ((0.0, 1975.5), (0.07, 2637.0)):
        i = int(d * SR); tt = t[: n - i]; x[i:] += np.sin(2 * np.pi * f * tt) * np.exp(-tt * 9)
    return x / np.abs(x).max()

def snip():
    x = np.zeros(int(0.12 * SR)); a = tick(0.015, 5200); b = tick(0.015, 4300)
    x[: len(a)] += a; i = int(0.045 * SR); x[i:i + len(b)] += 0.9 * b
    return x / np.abs(x).max()

def rain(dur):
    n = int(dur * SR); t = np.arange(n) / SR
    x = svf_bp(rng.standard_normal(n), np.full(n, 2400.0), 0.6) * 0.5
    drops = np.zeros(n)
    for k in range(int(dur * 18)):
        i = int(rng.random() * (n - 2000)); d = tick(0.01, 3000 + 2500 * rng.random()); drops[i:i + len(d)] += 0.6 * d
    x = (x + drops) * env(n, 0.15, 1.0)
    return x / np.abs(x).max()

W = 0.15
st = lambda i: S[i]["start"]
end = lambda i: S[i]["start"] + S[i]["dur"]
def exit_w(i): put(end(i) - 0.28, whoosh(0.32, 2200, 700, 1.4, 0.3), W * 0.45)
# ---------------------------------------------------------------- s01 hook: mini-reel wall, ring hops, credit panel, 0 stamp
put(0.02, rise(0.6, 300, 1200), 0.05)
for k in range(4): put(0.02 + k * 0.05, pop(500 + 90 * k, 900 + 90 * k, 0.07), 0.07)
tAn = wt("animasi")
for k in range(4): put(tAn - 0.08 + k * 0.08, tick(0.02, 3000 + 200 * k), 0.12)
tKa, tGi = wt("kayak"), wt("gini,")
for t in (tKa - 0.06, tKa + 0.2, tGi + 0.05, tGi + 0.3): put(t, whoosh(0.18, 1600, 3200, 2.0, 0.3), W * 0.35); put(t + 0.08, tick(0.02, 2400), 0.1)
for k in range(4): put(wt("bikin") - 0.06 + k * 0.06, pop(700 + 120 * k, 1200 + 120 * k, 0.05), 0.07)
put(wt("tanpa") - 0.14, whoosh(0.45, 600, 2400, 1.2, 0.5), W * 0.6); put(wt("tanpa") + 0.12, boom(0.3, 160, 80), 0.12)
put(wt("kredit") - 0.02, coin(), 0.09)
put(wt("video") - 0.04, rip(0.25), 0.06)
put(wt("AI") - 0.1, pop(400, 1100, 0.1), 0.15)
put(wt("sama") + 0.04, chime((1568, 2093), 0.6), 0.05)
put(wt("sekali.") - 0.05, boom(0.45, 150, 60), 0.28); put(wt("sekali.") - 0.03, pop(300, 140, 0.12), 0.18)
exit_w("s01")
# ---------------------------------------------------------------- s02 idea -> code
put(st("s02") + 0.0, whoosh(0.4, 2400, 700, 1.4, 0.4), W * 0.5); put(st("s02") + 0.1, whoosh(0.45, 500, 1800, 1.4, 0.45), W * 0.4)
put(wt("Claude") - 0.12, chime((1046, 1318, 1568), 0.9), 0.06); put(wt("Claude") + 0.02, pop(900, 500, 0.1), 0.1)
typing(wt("satu") - 0.04, wt("satu") - 0.04 + 39 / 44, 0.1, 22)
put(wt("ide,") - 0.06, pop(800, 1500, 0.08), 0.13); put(wt("ide,") + 0.02, chime((2093, 2637), 0.5), 0.05)
put(wt("terus") - 0.12, tick(0.03, 1500), 0.22); put(wt("terus") - 0.06, whoosh(0.35, 800, 3000, 1.6, 0.3), W * 0.4)
t0c = wt("terus") - 0.05; dtc = (wt("kode.") - 0.15 - t0c) / 11
for i in range(11): put(t0c + i * dtc, tick(0.016, 3400 + 90 * (i % 4)), 0.09)
for i in range(3): put(wt("seluruh") - 0.05 + i * 0.16, pop(700 + 150 * i, 1200 + 150 * i, 0.07), 0.1)
put(wt("jadi", 8) - 0.04, pop(600, 1300, 0.09), 0.14); put(wt("kode.") - 0.08, chime((1318.5, 1760, 2637), 1.0), 0.06)
exit_w("s02")
# ---------------------------------------------------------------- s03 video-AI vs code
put(st("s03") + 0.0, whoosh(0.45, 600, 2200, 1.3, 0.45), W * 0.5)
put(wt("model") - 0.0, tick(0.03, 1700), 0.15)
put(wt("AI,") - 0.06, buzz(0.22), 0.06); put(wt("AI,") - 0.08, pop(500, 200, 0.1), 0.15)
put(wt("tapi") - 0.14, whoosh(0.45, 600, 2200, 1.3, 0.45), W * 0.5); put(wt("tapi") + 0.1, pop(700, 1100, 0.08), 0.1)
typing(wt("HTML") - 0.06, wt("HTML") + 0.54, 0.08, 20); typing(wt("sama", 11) - 0.04, wt("sama", 11) + 0.46, 0.08, 20); typing(wt("animasi.") - 0.1, wt("animasi.") + 0.6, 0.08, 20)
tGo = wt("animasi.") + 0.55; put(tGo, whoosh(1.2, 300, 900, 0.9, 0.5), W * 0.35); put(tGo + 0.1, bloop(), 0.07)
put(wt("nggak") - 0.04, chime((1568, 2093, 2637), 0.8), 0.06)
for i in range(10): put(wt("nggak") - 0.05 + i * 0.03, tick(0.012, 4000 + 60 * i), 0.04)
tc0 = wt("kredit", 13) - 0.1; cdt = (wt("kepotong.") + 0.45 - tc0) / 7
for k in range(7): put(tc0 + k * cdt + cdt * 0.7, snip(), 0.12); put(tc0 + k * cdt + cdt * 0.75 + 0.2, pop(300, 120, 0.08), 0.06)
exit_w("s03")
# ---------------------------------------------------------------- s04 the four showcase mini-reels
T4 = st("s04")
for k in range(4): put(T4 + 0.02 + k * 0.06, tick(0.02, 2600 + 150 * k), 0.08)
put(T4 + 0.04, whoosh(0.45, 500, 1800, 1.3, 0.45), W * 0.5)
tBe = wt("bebas.")
put(tBe - 0.05, square_blips([660, 880, 990, 1320], 0.15), 0.05)
tCe, tKa2, tKo, tSa = wt("Cerita"), wt("Kartun"), wt("Kolam"), wt("Sampai")
FL = [(T4 + 0.22, tCe + 0.02), (tKa2 - 0.14, tKa2 + 0.2), (tKo - 0.12, tKo + 0.2), (tSa - 0.04, tSa + 0.3)]
for on, wp in FL:
    for i in range(3): put(on + 0.03 + i * 0.09, tick(0.014, 3600), 0.08)
    put(wp - 0.26, zap(0.28), 0.04); put(wp - 0.02, whoosh(0.3, 1500, 4200, 1.8, 0.3), W * 0.45)
# cerita anak: shooting star, moon rise, stars + constellation
put(wt("tidur,") + 0.1, whoosh(0.5, 3000, 6500, 2.4, 0.3), W * 0.25)
put(wt("bulan") - 0.15, chime((784, 988, 1175, 1568), 1.6), 0.05)
for i in range(5): put(wt("bintangnya.") - 0.05 + i * 0.09, chime((2093 + 200 * i, 3136 + 150 * i), 0.4), 0.035)
# kartun: idle hop, big boings, landings, BOING!
tJ = wt("lompat-lompat.") - 0.04; tt0 = tKa2 - 0.16
put(tt0 + 0.05 + 0.08, boing(0.3, 220, 380), 0.04)
t = max(tt0 + 0.05 + 0.5, tJ - 0.08)
while t <= (tKo + 0.4) - 0.3:
    put(t + 0.08, boing(), 0.09); put(t + 0.56, pop(160, 70, 0.12), 0.14); t += 0.62
put(tJ + 0.25, pop(500, 1300, 0.1), 0.12)
# kolam koi: bloops, splash on "beneran"
for i, dt_ in enumerate((0.15, 0.7, 1.3, 2.0)): put(tKo + dt_, bloop(240 + 40 * i, 800 + 60 * i), 0.05)
put(wt("beneran") - 0.05, splash(0.8), 0.12); put(wt("beneran") - 0.04, bloop(180, 700, 0.18), 0.1)
# film pendek: rain bed, clapperboard, subtitle
put(tSa - 0.06, rain(end("s04") - tSa + 0.06), 0.035)
put(wt("film") - 0.02, clack(), 0.3)
put(wt("ceritanya.") - 0.05, chime((659, 988, 1318.5), 1.2), 0.04)
exit_w("s04")
# ---------------------------------------------------------------- s05 HyperFrames: header, chips, terminal, render
T5 = st("s05")
put(T5 + 0.0, whoosh(0.45, 600, 2400, 1.3, 0.5), W * 0.5); put(T5 + 0.08, pop(500, 900, 0.1), 0.12)
put(T5 + 0.22, whoosh(0.4, 500, 1800, 1.4, 0.4), W * 0.35)
typing(wt("HyperFrames,") - 0.06, wt("HyperFrames,") - 0.06 + 11 / 26, 0.1, 24)
put(wt("open") + 0.05, pop(800, 1300, 0.08), 0.12)
for t in (wt("open") - 0.06, wt("HeyGen.") - 0.08, wt("HeyGen.") + 0.35): put(t, pop(700, 1200, 0.08), 0.12)
typing(wt("Pasang") - 0.05, wt("perintah,"), 0.1, 26)
put(wt("satu", 30) - 0.04, pop(900, 1600, 0.08), 0.13)
put(wt("perintah,") + 0.25, chime((1568, 2093), 0.6), 0.05)
typing(wt("render") - 0.15, wt("render") - 0.15 + 22 / 34, 0.1, 26)
put(wt("render") + 0.1, rise(wt("sendiri.") - wt("render"), 300, 1400), 0.035)
put(wt("laptop") - 0.06, pop(700, 1100, 0.08), 0.1)
put(wt("sendiri.") + 0.05, pop(500, 1200, 0.1), 0.14); put(wt("sendiri.") + 0.12, chime((1318.5, 1760, 2637), 1.0), 0.06)
exit_w("s05")
# ---------------------------------------------------------------- s06 meta: pull-out, live pill, timeline, code chips, stamp
T6 = st("s06")
put(T6 + 0.0, whoosh(1.0, 3000, 400, 1.0, 0.4), W * 0.7); put(T6 + 0.85, pop(300, 150, 0.1), 0.12)
put(wt("ini?") - 0.06, pop(600, 1300, 0.1), 0.15); put(wt("ini?") - 0.04, chime((2093, 2637), 0.5), 0.04)
put(wt("Dibikin") - 0.12, whoosh(0.45, 600, 2200, 1.3, 0.45), W * 0.5)
for r in range(3): put(wt("persis") - 0.05 + r * 0.1, tick(0.02, 2800 + 200 * r), 0.1)
for t in (wt("animasi,") - 0.12, wt("teks,") - 0.12, wt("suaranya,") - 0.4): put(t, pop(600, 1000, 0.08), 0.12); put(t + 0.06, pop(900, 1500, 0.07), 0.1)
for k in range(6): put(wt("suaranya,") - 0.3 + k * 0.06, square_blips([440 + 110 * (k % 3)], 0.05), 0.03)
for r in range(3): put(wt("semuanya") - 0.05 + r * 0.06, tick(0.02, 3000 + 300 * r), 0.1)
put(wt("kode.", 40) - 0.04, boom(0.45, 150, 60), 0.28); put(wt("kode.", 40) - 0.02, pop(300, 140, 0.12), 0.18)
exit_w("s06")
# ---------------------------------------------------------------- s07 CTA
T7 = st("s07")
put(T7 + 0.0, whoosh(0.45, 500, 1800, 1.3, 0.5), W * 0.5)
for r in range(3): put(wt("panduan") + 0.12 + r * 0.16, pop(800 + 150 * r, 1400 + 150 * r, 0.07), 0.12)
put(wt("pasangnya?") + 0.1, pop(700, 1100, 0.08), 0.1)
put(wt("Komen") - 0.2, whoosh(0.4, 600, 2000, 1.4, 0.5), W * 0.5)
for k in range(5): put(wt("REELS,") - 0.06 + k * 0.07, tick(0.022, 4200), 0.15)
put(wt("REELS,") + 0.42, pop(900, 1600, 0.1), 0.15)
put(wt("aku", 42) - 0.08, whoosh(0.7, 700, 3600, 1.2, 0.5), W); put(wt("kirim") - 0.02, pop(600, 1000, 0.08), 0.1)
put(wt("DM.") - 0.06, chime((1568, 2093), 0.8), 0.07)
put(T["total_sec"] - 1.4, chime((1046, 1568, 2093, 2637), 1.6), 0.07)
x = np.clip(out, -1, 1); x = (x * 32767).astype(np.int16)
f = wave.open(str(P / "assets/audio/sfx.wav"), "wb"); f.setnchannels(1); f.setsampwidth(2); f.setframerate(SR); f.writeframes(x.tobytes()); f.close()
print("sfx.wav", round(len(x) / SR, 2), "s, peak", round(float(np.abs(out).max()), 3))
